module prienc8(input [7:0] in, output [2:0] idx, output valid);
  assign valid = |in;
  wire hi = |in[7:4];
  assign idx[2] = hi;
  // idx1: 7,6 -> 1 ; 5,4 -> 0 ; 3,2 -> 1 ; 1,0 -> 0
  assign idx[1] = hi ? (in[7]|in[6]) : (in[3]|in[2]);
  assign idx[0] = hi ? (in[7] | (~in[6] & in[5])) : (in[3] | (~in[2] & in[1]));
endmodule

module prienc8(input [7:0] in, output [2:0] idx, output valid);
  wire hi = |in[7:4];
  wire g = in[3]|in[2];
  assign valid = hi | g | in[1] | in[0];
  assign idx[2] = hi;
  assign idx[1] = hi ? (in[7]|in[6]) : g;
  wire t = ~in[4] & (in[3] | (~in[2] & in[1]));
  assign idx[0] = in[7] | (~in[6] & (in[5] | t));
endmodule
